package com.matejpcs.netflared;
import com.google.gson.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;
public final class ServerConfig{private static final Gson G=new GsonBuilder().setPrettyPrinting().create();private final Path f;private boolean enabled;private String accountId="",zoneId="",zoneName="",tunnelId="",tunnelName="",tunnelToken="",hostname="";private int port=25565;public ServerConfig(Path d){f=d.resolve("config.json");}public void load()throws IOException{if(!Files.exists(f)){save();return;}JsonObject r=G.fromJson(Files.readString(f,StandardCharsets.UTF_8),JsonObject.class);if(r==null)return;enabled=b(r,"enabled",false);accountId=s(r,"accountId");zoneId=s(r,"zoneId");zoneName=s(r,"zoneName");tunnelId=s(r,"tunnelId");tunnelName=s(r,"tunnelName");tunnelToken=s(r,"tunnelToken");hostname=s(r,"hostname");port=r.has("serverPort")?r.get("serverPort").getAsInt():25565;}public synchronized void save()throws IOException{Files.createDirectories(f.getParent());JsonObject r=new JsonObject();r.addProperty("enabled",enabled);r.addProperty("accountId",accountId);r.addProperty("zoneId",zoneId);r.addProperty("zoneName",zoneName);r.addProperty("tunnelId",tunnelId);r.addProperty("tunnelName",tunnelName);r.addProperty("tunnelToken",tunnelToken);r.addProperty("hostname",hostname);r.addProperty("serverPort",port);Files.writeString(f,G.toJson(r),StandardCharsets.UTF_8);}private static String s(JsonObject o,String k){return o.has(k)?o.get(k).getAsString():"";}private static boolean b(JsonObject o,String k,boolean d){return o.has(k)?o.get(k).getAsBoolean():d;}public boolean isConfigured(){return enabled&&!tunnelId.isBlank()&&!tunnelToken.isBlank();}public void setEnabled(boolean v){enabled=v;}public String accountId(){return accountId;}public void setAccountId(String v){accountId=v;}public String zoneId(){return zoneId;}public void setZoneId(String v){zoneId=v;}public String zoneName(){return zoneName;}public void setZoneName(String v){zoneName=v;}public String tunnelId(){return tunnelId;}public void setTunnelId(String v){tunnelId=v;}public String tunnelName(){return tunnelName;}public void setTunnelName(String v){tunnelName=v;}public String tunnelToken(){return tunnelToken;}public void setTunnelToken(String v){tunnelToken=v;}public String hostname(){return hostname;}public void setHostname(String v){hostname=v;}public int serverPort(){return port;}public void setServerPort(int v){port=v;}}
